interface Org {
  [key: string]: unknown;
}

interface User {
  id: string;
  orgId: string;
  org?: Org;
}

async function loadUser(id: string): Promise<User> {
  const userRes = await fetch(`/api/users/${id}`);
  if (!userRes.ok) {
    throw new Error(`bad status ${userRes.status}`);
  }

  const user = (await userRes.json()) as User;
  if (!user.orgId) {
    throw new Error('missing orgId');
  }

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }

  user.org = (await orgRes.json()) as Org;
  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };

interface Org {
  id?: string;
  name?: string;
  [key: string]: unknown;
}

interface User {
  id?: string;
  orgId: string;
  org?: Org;
  [key: string]: unknown;
}

async function loadUser(id: string): Promise<User> {
  const userRes = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!userRes.ok) {
    throw new Error(`bad status ${userRes.status}`);
  }

  const user = (await userRes.json()) as User;

  const orgRes = await fetch(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }

  user.org = (await orgRes.json()) as Org;
  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

